function s(n){let e=Math.max(0,Math.floor(n.lockedQuantity??0));return Math.max(0,n.quantity-e)}function d(n,e){return n.filter(r=>r.itemId===e).reduce((r,o)=>r+s(o),0)}function f(n,e){return n.filter(r=>r.itemId===e).reduce((r,o)=>r+o.quantity,0)}function y(n,e){if(e<=0){let{lockedQuantity:r,...o}=n;return o}return{...n,lockedQuantity:e}}function m(n,e,r){let o=Math.floor(r);if(!Number.isFinite(o)||o<=0)return{ok:!1,reason:"Quantidade inv\xE1lida."};if(d(n,e)<o)return{ok:!1,reason:n.some(i=>i.itemId===e)?"Quantidade indispon\xEDvel (itens bloqueados ou insuficientes).":"Item n\xE3o pertence ao invent\xE1rio."};let a=o;return{ok:!0,stacks:n.map(t=>{if(t.itemId!==e||a<=0)return{...t};let i=s(t);if(i<=0)return{...t};let c=Math.min(i,a);return a-=c,{...t,lockedQuantity:(t.lockedQuantity??0)+c}})}}function k(n,e,r){let o=Math.floor(r);if(o<=0)return n.map(t=>({...t}));let a=o,u=n.map(t=>({...t}));for(let t=u.length-1;t>=0&&a>0;t-=1){let i=u[t];if(i.itemId!==e)continue;let c=Math.max(0,Math.floor(i.lockedQuantity??0));if(c<=0)continue;let l=Math.min(c,a);a-=l,u[t]=y(i,c-l)}return u}function I(n,e,r){let o=Math.floor(r);if(!Number.isFinite(o)||o<=0)return{ok:!1,reason:"Quantidade inv\xE1lida."};if(f(n,e)<o)return{ok:!1,reason:n.some(i=>i.itemId===e)?"Quantidade insuficiente no invent\xE1rio.":"Item n\xE3o encontrado no invent\xE1rio."};let a=o,u=[];for(let t of n){if(t.itemId!==e||a<=0){u.push({...t});continue}if(t.quantity<=a){a-=t.quantity;continue}let i=t.quantity-a,c=Math.max(0,(t.lockedQuantity??0)-a);a=0,u.push(y({...t,quantity:i},c))}return{ok:!0,stacks:u.filter(t=>t.quantity>0)}}export{s as a,m as b,k as c,I as d};
